import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        String s = scanner.nextLine();

        StringBuilder ans = new StringBuilder();
        boolean flag = false;
        int i = 0;
        int length = s.length();

        while (i < length) {
            // Check for sequence "dot"
            if (i + 2 < length && i != 0) {
                String temp = s.substring(i, i + 3);
                if (temp.equals("dot")) {
                    ans.append('.');
                    i += 3;
                    continue;
                }
            }
            // Check for sequence "at" when not flagged and not at start
            if (i + 1 < length && !flag && i != 0) {
                String temp = s.substring(i, i + 2);
                if (temp.equals("at")) {
                    ans.append('@');
                    i += 2;
                    flag = true;
                    continue;
                }
            }
            // When sequence check fails, append character
            ans.append(s.charAt(i));
            i++;
        }

        System.out.println(ans.toString());
        scanner.close();
    }
}
